document.querySelectorAll('[data-lab="L08-I1"]').forEach(root=>{if(root.dataset.ready)return;root.dataset.ready='1';const zh=root.dataset.lang==='zh',r=root.querySelector('[data-r]'),k=root.querySelector('[data-k]'),mode=root.querySelector('[data-mode]'),out=root.querySelector('[data-readout]'),plot=root.querySelector('[data-plot]');function value(x,K){let u=x<Math.pow(2,1/6)?4*(x**-12-x**-6)+1:0,f=x<Math.pow(2,1/6)?24/x*(2*x**-12-x**-6):0;let b=-K*1.5**2/2*Math.log(1-(x/1.5)**2),fb=-K*x/(1-(x/1.5)**2);return mode.value==='wca'?[u,f]:mode.value==='elastic'?[b,fb]:[u+b,f+fb];}function update(){let R=+r.value,K=+k.value,[u,f]=value(R,K),X=x=>75+(x-.8)/.65*750,Y=y=>340-y/160*280;let points=[];for(let j=0;j<=400;j++){let a=.8+.65*j/400;points.push(X(a)+','+Y(value(a,K)[0]));}let s='<rect width="900" height="420" fill="#f8f7f2"/><path d="M75 60V340H825" stroke="#163840" fill="none"/>';for(let a of [.8,.9,1,1.1,1.2,1.3,1.4,1.45])s+=`<text x="${X(a)}" y="370" text-anchor="middle" font-size="18">${a}</text>`;for(let a of [0,40,80,120,160])s+=`<text x="62" y="${Y(a)+6}" text-anchor="end" font-size="18">${a}</text>`;s+='<text x="75" y="35" font-size="21">U / ε</text><text x="780" y="405" font-size="21">r / σ</text>';s+=`<polyline points="${points.join(' ')}" fill="none" stroke="#167d84" stroke-width="3"/><line x1="${X(R)}" y1="340" x2="${X(R)}" y2="${Y(u)}" stroke="#c16b3d" stroke-dasharray="5 5"/><circle cx="${X(R)}" cy="${Y(u)}" r="6" fill="#c16b3d"/>`;plot.innerHTML=s;out.textContent=`r = ${R.toFixed(2)} σ; K = ${K.toFixed(0)} ε/σ²; U = ${u.toFixed(5)} ε; Fᵣ = ${f.toFixed(5)} ε/σ. `+(zh?(f>1e-9?'正值推动距离增大。':f<-1e-9?'负值把两珠拉近。':'该项的力为零。'):(f>1e-9?'Positive force increases separation.':f<-1e-9?'Negative force pulls the beads together.':'This force contribution is zero.'));}for(let control of [r,k,mode])control.addEventListener('input',update);root.querySelector('[data-reset]').addEventListener('click',()=>{r.value=.97;k.value=30;mode.value='total';update();});update();});